    async function pickDate(yyyyMmDd: any) {

    	let dp: any = new TestObject('dp')
    	dp.addProperty("xpath", ConditionType.EQUALS,
    		"//*[@id='ui-datepicker-div' and not(contains(@style,'display: none'))]"
    	)
    	await WebUI.waitForElementVisible(dp, 20)

    	let parts: any = yyyyMmDd.split('-')
    	let targetYear: any = parts[0]
    	let targetMonthIndex: any = (parts[1]) - 1
    	let targetDay: any = String(parts[2])

    	let nextBtn: any = new TestObject('dpNext')
    	nextBtn.addProperty("xpath", ConditionType.EQUALS,
    		"//*[@id='ui-datepicker-div']//a[contains(@class,'ui-datepicker-next')]"
    	)

    	let prevBtn: any = new TestObject('dpPrev')
    	prevBtn.addProperty("xpath", ConditionType.EQUALS,
    		"//*[@id='ui-datepicker-div']//a[contains(@class,'ui-datepicker-prev')]"
    	)

    	let guard: any = 0
    	while (guard < 48) {

    		let targetDayObj: any = new TestObject(`targetDay_${targetYear}_${targetMonthIndex}_${targetDay}`)
    		targetDayObj.addProperty("xpath", ConditionType.EQUALS,
    			`//*[@id='ui-datepicker-div']//td[@data-year='${targetYear}' and @data-month='${targetMonthIndex}' ` +
    			`and not(contains(@class,'ui-state-disabled'))]//a[normalize-space()='${targetDay}']`
    		)

    		if (await WebUI.verifyElementPresent(targetDayObj, 1, FailureHandling.OPTIONAL)) {
    			await WebUI.waitForElementClickable(targetDayObj, 20)
    			await WebUI.click(targetDayObj)
    			return
    		}

    		// kalau target belum ada, click next dulu
    		await WebUI.click(nextBtn)
    		await WebUI.delay(0.3)
    		guard++
    	}

    	await WebUI.takeScreenshot()
    	gAssert(false, "Date not found in datepicker: " + yyyyMmDd)
    }
